import{_ as e,a as o,o as a,a4 as r}from"./chunks/framework.-FZumj2l.js";const h=JSON.parse('{"title":"Promotions","description":"","frontmatter":{"outline":false},"headers":[],"relativePath":"api/rest-api/admin/marketing/promotions/index.md","filePath":"api/rest-api/admin/marketing/promotions/index.md","lastUpdated":1783327468000}'),n={name:"api/rest-api/admin/marketing/promotions/index.md"};function s(i,t,c,p,d,u){return a(),o("div",null,t[0]||(t[0]=[r('<h1 id="promotions" tabindex="-1">Promotions <a class="header-anchor" href="#promotions" aria-label="Permalink to &quot;Promotions&quot;">​</a></h1><p>Promotions are the store&#39;s <strong>discounting engine</strong>. There are two kinds, and they fire at different moments in the shopping journey.</p><h2 id="the-two-rule-types" tabindex="-1">The two rule types <a class="header-anchor" href="#the-two-rule-types" aria-label="Permalink to &quot;The two rule types&quot;">​</a></h2><p><strong>Catalog Rules — change the price <em>before</em> the cart.</strong> A catalog rule rewrites a product&#39;s displayed price store-wide, automatically, for everyone (or a chosen customer group / channel) who meets its conditions. No coupon, no minimum cart — the shopper just sees a lower price on the product and category pages. Use it for &quot;10% off the whole Summer collection&quot; or &quot;wholesale group always pays 15% less&quot;. Because it recomputes product prices, saving a catalog rule triggers a price re-index in the background.</p><p><strong>Cart Rules — discount the <em>cart</em> at checkout.</strong> A cart rule applies to the cart total once the shopper has added items, optionally gated by a <strong>coupon code</strong> and by conditions (cart subtotal over X, specific products present, etc.). Use it for &quot;free shipping over $100&quot;, &quot;$20 off with code WELCOME20&quot;, or &quot;buy-X-get-Y&quot;. A cart rule that uses a specific coupon code draws that code (and any bulk-generated batch) from <strong>Cart Rule Coupons</strong>.</p><table tabindex="0"><thead><tr><th>Resource</th><th>What it does</th></tr></thead><tbody><tr><td><a href="/api/rest-api/admin/marketing/promotions/catalog-rules/">Catalog Rules</a></td><td>Automatic product-price reductions applied store-wide before checkout.</td></tr><tr><td><a href="/api/rest-api/admin/marketing/promotions/cart-rules/">Cart Rules</a></td><td>Discounts applied to the cart at checkout, optionally coupon-gated.</td></tr><tr><td><a href="/api/rest-api/admin/marketing/promotions/cart-rule-coupons/">Cart Rule Coupons</a></td><td>The coupon codes (single or bulk-generated) that activate a coupon-driven cart rule.</td></tr></tbody></table><h2 id="how-they-relate" tabindex="-1">How they relate <a class="header-anchor" href="#how-they-relate" aria-label="Permalink to &quot;How they relate&quot;">​</a></h2><p>A <strong>Catalog Rule</strong> and a <strong>Cart Rule</strong> can both touch the same order: the catalog rule lowers the per-product price the shopper sees, then the cart rule discounts the resulting cart total. <strong>Cart Rule Coupons</strong> exist only to feed a cart rule whose coupon type is <em>specific code</em> — they are a sub-resource of a single cart rule, not a standalone promotion.</p><p>All Promotions endpoints require an admin Bearer token — see <a href="/api/rest-api/admin/authentication.html">Authentication</a>.</p>',9)]))}const m=e(n,[["render",s]]);export{h as __pageData,m as default};
